-		return false;
-	}
-
-	@Override
-	public Set<String> getTrailerNames() {
-		return Set.of();
-	}
-
-	@Override
-	public String getContentType() {
-		return CONTENT_TYPE;
-	}
-
-	@Override
-	public String getContentEncoding() {
-		//Apparently this is the correct value:
-		return null;
