-		setDistancesIfNecessary();
-		return distances[distanceIndex++];
-	}
-
-	@Override
-	public int docValueCount() {
-		return values.docValueCount();
-	}
-
-	@Override
-	public boolean advanceExact(int doc) throws IOException {
-		distanceIndex = -1;
-		return values.advanceExact( doc );
-	}
-
