+						.memberTypeReference( getterGenericReturnType() );
+			}
+			catch (RuntimeException e) {
+				throw log.errorRetrievingPropertyTypeModel( name(), holderTypeModel, e );
+			}
+		}
+		return typeModelCache;
+	}
+
