+	public final ValueReadHandle<T> handle() {
+		if ( handleCache == null ) {
+			try {
+				handleCache = createHandle( member() );
+			}
+			catch (ReflectiveOperationException | RuntimeException e) {
+				throw log.errorRetrievingPropertyTypeModel( name(), holderTypeModel, e );
+			}
+		}
+		return handleCache;
+	}
+
